private int parseEndOfLine(String headerPart,int end){
    if(headerPart == null || end < 0 || end >= headerPart.length()){
        return -1;
    }
    int limit = headerPart.length() - 1;
    for(int i = end; i < limit; i++){
        if(headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    if(headerPart == null) {
        return -1;
    }
    int len = headerPart.length();
    if(end < 0) {
        end = 0;
    }
    if(end >= len) {
        return -1;
    }
    for(int i = end; i < len - 1; i++) {
        char c = headerPart.charAt(i);
        if(c == '\r') {
            if(headerPart.charAt(i + 1) == '\n') {
                return i;
            }
        } else if(c == '\n') {
            return i;
        }
    }
    if(len > 0 && headerPart.charAt(len - 1) == '\n') {
        return len - 1;
    }
    return -1;
}

private int parseEndOfLine(String headerPart, int end) {
    // Validate input
    if (headerPart == null) {
        // No header to parse; return -1 indicating not found
        return -1;
    }
    // Determine starting position for the search
    int startIndex = Math.max(0, end + 1);
    if (startIndex >= headerPart.length()) {
        // No more characters to inspect
        return -1;
    }
    // Search for the CRLF sequence ("\r\n") starting from startIndex
    int lineEndIndex = headerPart.indexOf("\r\n", startIndex);
    // Return the index of the start of the CRLF, or -1 if not found
    return lineEndIndex;
}

