public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Example: construct a 3-4 complete bipartite graph (3 vertices on one side, 4 on the other)
    int sideSizeA = 3;
    int sideSizeB = 4;

    // Add vertices for side A
    for (int i = 0; i < sideSizeA; i++) {
        String key = "U" + i;
        @SuppressWarnings("unchecked")
        V vertex = (V) (Object) key; // casting string to V; assumes V is String or compatible
        target.addVertex(vertex);
        resultMap.put(key, vertex);
    }

    // Add vertices for side B
    for (int j = 0; j < sideSizeB; j++) {
        String key = "V" + j;
        @SuppressWarnings("unchecked")
        V vertex = (V) (Object) key;
        target.addVertex(vertex);
        resultMap.put(key, vertex);
    }

    // Add all edges between vertices of the two sides
    for (Map.Entry<String, V> entryA : resultMap.entrySet()) {
        if (!entryA.getKey().startsWith("U")) continue;
        V u = entryA.getValue();
        for (Map.Entry<String, V> entryB : resultMap.entrySet()) {
            if (!entryB.getKey().startsWith("V")) continue;
            V v = entryB.getValue();
            target.addEdge(u, v);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if (target == null) throw new IllegalArgumentException("target graph cannot be null");
    try{
        // create two partition sets
        int partUSize = 3; // size of U side
        int partVSize = 4; // size of V side
        // add vertices to U side
        for (int i=0; i<partUSize; i++){
            @SuppressWarnings("unchecked")
            V vertex = (V)(Object)("U"+i);
            target.addVertex(vertex);
            resultMap.put("U"+i, vertex);
        }
        // add vertices to V side
        for (int j=0; j<partVSize; j++){
            @SuppressWarnings("unchecked")
            V vertex = (V)(Object)("V"+j);
            target.addVertex(vertex);
            resultMap.put("V"+j, vertex);
        }
        // add all edges between U and V vertices creating a complete bipartite graph
        for (int i=0; i<partUSize; i++){
            @SuppressWarnings("unchecked")
            V u = (V)(Object)("U"+i);
            for (int j=0; j<partVSize; j++){
                @SuppressWarnings("unchecked")
                V v = (V)(Object)("V"+j);
                target.addEdge(u, v);
            }
        }
    }catch (Exception e){
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if (target == null || resultMap == null) return;
    // Separate vertices into two groups based on key prefix
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    for (Map.Entry<String,V> entry : resultMap.entrySet()){
        String key = entry.getKey();
        V vertex = entry.getValue();
        if (key == null || vertex == null) continue;
        // ensure vertex is in graph
        if (!target.containsVertex(vertex)){
            target.addVertex(vertex);
        }
        if (key.startsWith("L") || key.startsWith("l")){
            left.add(vertex);
        } else if (key.startsWith("R") || key.startsWith("r")){
            right.add(vertex);
        } else {
            // fallback: alternate assignment
            if (left.size() <= right.size()){
                left.add(vertex);
            } else {
                right.add(vertex);
            }
        }
    }
    // Create complete bipartite connections
    for (V u : left){
        for (V v : right){
            if (!target.containsEdge(u, v)){
                target.addEdge(u, v);
            }
        }
    }
}

@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    final int leftCount = 3;
    final int rightCount = 3;
    int id = 0;
    List<V> leftVertices = new ArrayList<>();
    List<V> rightVertices = new ArrayList<>();
    // Create left vertices
    for (int i = 0; i < leftCount; i++) {
        V v = (V) Integer.valueOf(id++);
        target.addVertex(v);
        leftVertices.add(v);
        resultMap.put("L" + i, v);
    }
    // Create right vertices
    for (int i = 0; i < rightCount; i++) {
        V v = (V) Integer.valueOf(id++);
        target.addVertex(v);
        rightVertices.add(v);
        resultMap.put("R" + i, v);
    }
    // Add all edges between left and right partitions
    for (V u : leftVertices) {
        for (V w : rightVertices) {
            target.addEdge(u, w);
        }
    }
}

