        }

        // Write the length of the message as a varint to the output stream.
        int v = messageSize;
        while ((v & ~0x7F) != 0) {
            out.write((v & 0x7F) | 0x80);
            v >>>= 7;
        }
        out.write(v);

        // Serialize the actual message into the buffer first.
        schema.writeTo(buffer, message);

        // Transfer the bytes from the buffer into the output stream.
        ByteBuffer src = buffer.getProduced();
        while (src.hasRemaining()) {
            out.write(src.get());
        }

        return messageSize;
    } catch (IOException e) {
        // Propagate as required.
        throw e;
    } catch (Exception e) {
        // Wrap unexpected exceptions in an IOException.
        throw new IOException("Failed to write delimited message", e);
    } finally {
