private static Class<?> resolveConcreteType(Type type) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        Type raw = ((ParameterizedType) type).getRawType();
        return raw instanceof Class<?> ? (Class<?>) raw : null;
    }
    if (type instanceof GenericArrayType) {
        Type component = ((GenericArrayType) type).getGenericComponentType();
        Class<?> compClass = resolveConcreteType(component);
        if (compClass == null) {
            return null;
        }
        return java.lang.reflect.Array.newInstance(compClass, 0).getClass();
    }
    if (type instanceof WildcardType) {
        Type[] bounds = ((WildcardType) type).getUpperBounds();
        if (bounds.length > 0) {
            return resolveConcreteType(bounds[0]);
        }
    }
    // TypeVariable or other unresolvable type
    return null;
}

