protected List<TimeRange> buildTimeRanges(long start,long end){
    if (start > end) {
        throw new IllegalArgumentException("Start time must not be greater than end time");
    }
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Start and end times must be non‑negative");
    }
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalStateException("FETCH_DATA_DURATION must be a positive value");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long currStart = start;
    while (currStart < end) {
        long currEnd = Math.min(currStart + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(currStart, currEnd));
        currStart = currEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
    }
    long s = start;
    long e = end;
    if (s > e) {
        long temp = s;
        s = e;
        e = temp;
    }
    while (s < e) {
        long next;
        try {
            next = Math.min(Math.addExact(s, FETCH_DATA_DURATION), e);
        } catch (ArithmeticException ex) {
            next = e; // overflow, use the remaining range
        }
        ranges.add(new TimeRange(s, next));
        s = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end){
    List<TimeRange> ranges = new ArrayList<TimeRange>();
    if (start >= end) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long next;
        if (Long.MAX_VALUE - current < FETCH_DATA_DURATION) {
            next = end;
        } else {
            next = Math.min(end, current + FETCH_DATA_DURATION);
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

