    }
    if (start >= end) {
        return ranges;
    }
    while (start < end) {
        long next;
        if (start > Long.MAX_VALUE - FETCH_DATA_DURATION) {
            next = end;
        } else {
            next = Math.min(start + FETCH_DATA_DURATION, end);
        }
        ranges.add(new TimeRange(start, next));
        start = next;
    }
    return ranges;
}

