public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null) {
        return 0;
    }
    int strLen = str.length();
    // Normalize index and length
    int start = index;
    int length = len;
    if (start < 0) {
        start = 0;
    }
    if (length < 0) {
        return 0;
    }
    int end = start + length;
    if (end > strLen) {
        end = strLen;
    }
    if (start >= end) {
        return 0;
    }
    int size = 0;
    int i = start;
    while (i < end) {
        int codePoint = str.codePointAt(i);
        if (codePoint <= 0x7F) {
            size += 1;
        } else if (codePoint <= 0x7FF) {
            size += 2;
        } else if (codePoint <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        i += Character.charCount(codePoint);
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null || len <= 0) return 0;
    int strLen = str.length();
    if (index < 0 || index >= strLen) return 0;
    int end = index + len;
    if (end > strLen) end = strLen;
    int count = 0;
    int i = index;
    while (i < end) {
        int codeUnit = str.charAt(i);
        if (codeUnit < 0x80) {
            count++;
        } else if (codeUnit < 0x800) {
            count += 2;
        } else if (codeUnit >= 0xD800 && codeUnit <= 0xDBFF) {
            if (i + 1 < end) {
                int low = str.charAt(i + 1);
                if (low >= 0xDC00 && low <= 0xDFFF) {
                    count += 4;
                    i++; // skip low surrogate
                } else {
                    count += 3; // malformed surrogate pair
                }
            } else {
                count += 3; // trailing high surrogate
            }
        } else if (codeUnit >= 0xDC00 && codeUnit <= 0xDFFF) {
            count += 3; // low surrogate without preceding high surrogate
        } else {
            count += 3;
        }
        i++;
    }
    return count;
}

