    if (str == null || len <= 0) {
        return 0;
    }
    int start = Math.max(0, index);
    int maxStart = str.length();
    if (start >= maxStart) {
        return 0;
    }
    int actualLen = Math.min(len, maxStart - start);
    int end = start + actualLen;
    int size = 0;
    for (int i = start; i < end; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c) && i + 1 < end
                && Character.isLowSurrogate(str.charAt(i + 1))) {
            size += 4;
            i++; // Skip low surrogate
        } else {
            size += 3;
        }
    }
    return size;
}

