private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // Both null => true
    if (str == null && suffix == null) {
        return true;
    }
    // One is null => false
    if (str == null || suffix == null) {
        return false;
    }
    final int suffixLen = suffix.length();
    final int strLen = str.length();

    // Empty suffix always matches
    if (suffixLen == 0) {
        return true;
    }

    // If suffix is longer than the string, can't match
    if (suffixLen > strLen) {
        return false;
    }

    // Use regionMatches for optional case-insensitive comparison
    // regionMatches handles empty suffix gracefully when suffixLen==0
    return str.regionMatches(ignoreCase, strLen - suffixLen, suffix, 0, suffixLen);
}

