private void pop(final String descriptor){
    int i = 0;
    if (descriptor.length() == 0) {
        return;
    }
    if (descriptor.charAt(0) == '(') {
        // Method descriptor: pop argument types until ')'
        i++; // skip '('
        while (descriptor.charAt(i) != ')') {
            char c = descriptor.charAt(i);
            switch (c) {
                case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                    pos--;
                    i++;
                    break;
                case 'D': case 'J':
                    pos -= 2;
                    i++;
                    break;
                case 'L':
                    // reference type
                    i++;
                    while (descriptor.charAt(i) != ';') {
                        i++;
                    }
                    pos--;
                    i++; // skip ';'
                    break;
                case '[':
                    // array type
                    while (descriptor.charAt(i) == '[') {
                        i++;
                    }
                    char comp = descriptor.charAt(i);
                    if (comp == 'L') {
                        i++;
                        while (descriptor.charAt(i) != ';') {
                            i++;
                        }
                        i++; // skip ';'
                    } else {
                        i++; // primitive component
                    }
                    pos--;
                    break;
                default:
                    throw new IllegalArgumentException("Unknown type character: " + c);
            }
        }
        // Skip ')'
        i++;
        // Return type follows; ignore it
    } else {
        // Single type descriptor
        char c = descriptor.charAt(i);
        switch (c) {
            case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                pos--;
                break;
            case 'D': case 'J':
                pos -= 2;
                break;
            case 'L':
                while (descriptor.charAt(i) != ';') {
                    i++;
                }
                pos--;
                break;
            case '[':
                while (descriptor.charAt(i) == '[') {
                    i++;
                }
                if (descriptor.charAt(i) == 'L') {
                    i++;
                    while (descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++; // skip ';'
                } else {
                    i++; // primitive component
                }
                pos--;
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}

private void pop(final String descriptor){
    int i = 0;
    final int len = descriptor.length();
    while (i < len) {
        char c = descriptor.charAt(i);
        if (c == '(') {
            i++;
            continue;
        }
        if (c == ')') {
            i++;
            break;
        }
        int slots = 1;
        if (c == '[') {
            while (i < len && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i < len && descriptor.charAt(i) == 'L') {
                i++;
                while (i < len && descriptor.charAt(i) != ';') {
                    i++;
                }
                i++;
            } else {
                i++;
            }
            slots = 1;
        } else if (c == 'L') {
            i++;
            while (i < len && descriptor.charAt(i) != ';') {
                i++;
            }
            i++;
            slots = 1;
        } else {
            i++;
            if (c == 'J' || c == 'D') {
                slots = 2;
            } else {
                slots = 1;
            }
        }
        pos -= slots;
    }
}

