    if (descriptor == null || descriptor.isEmpty() || pos <= 0) {
        return;
    }
    int count = 0;
    int i = 0;
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor; pop all argument types
        i = 1;
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            // Skip array brackets
            while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= descriptor.length()) {
                break;
            }
            char c = descriptor.charAt(i);
            if (c == 'L') {
                // object reference: find terminating ';'
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon < 0) {
                    break; // malformed descriptor
                }
                i = semicolon + 1;
            } else {
                // Primitive type (I,J,D,F,Z,B,C,S,V)
                i++;
            }
            count++;
        }
    } else {
        // Regular type descriptor: pop a single type
        // For correctness, still parse once (handles array/object)
        // Skip array brackets
        while (i < descriptor.length() && descriptor.charAt(i) == '[') {
            i++;
        }
        if (i < descriptor.length()) {
            if (descriptor.charAt(i) == 'L') {
                int semicolon = descriptor.indexOf(';', i);
                // If malformed, just consider up to end
                if (semicolon < 0) {
                    semicolon = descriptor.length() - 1;
                }
                i = semicolon + 1;
            } else {
                i++;
            }
            count = 1;
        }
    }
    // Adjust the stack pointer, ensuring it stays within bounds
    pos -= count;
    if (pos < 0) {
        pos = 0;
    }
