        i++; // skip '('
        while (i < descriptor.length() && descriptor.charAt(i) != ')'){
            while (descriptor.charAt(i) == '[') i++;
            char c = descriptor.charAt(i);
            if (c == 'L'){
                int end = descriptor.indexOf(';', i);
                if (end == -1) throw new IllegalArgumentException("Invalid descriptor");
                i = end + 1;
