                int end = descriptor.indexOf(';', i);
                if (end == -1) throw new IllegalArgumentException("Invalid descriptor");
                i = end + 1;
            }else{
                i++; // primitive
            }
            types++;
            break; // only one type for non-method descriptor
        }
    }
    if (types > pos) throw new IllegalStateException("Stack underflow");
    pos -= types;
