        for(String s:searchStrArray){ 
            if(s==null) continue; 
            for(char c:s.toString().toLowerCase()){ 
                searchChars.add(c); 
            } 
        } 
        for(char c:str.toString().toLowerCase()){ 
            if(searchChars.contains(c)){ 
                return true; 
            } 
        } 
        return false; 
    }catch(Exception e){ 
        return false; 
    } 
}

