private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Objects.requireNonNull(predicate, "predicate must not be null");
    Objects.requireNonNull(start, "start node must not be null");
    Objects.requireNonNull(stop, "stop node must not be null");

    Node current = start;

    // Return immediately if the start node satisfies the predicate or is the stop node
    if (predicate.apply(current) || current == stop) {
        return new OuterFaceCirculator(current, dir);
    }

    // Traverse outward-face links until we hit a node that satisfies the predicate
    // or reach the stop node.  Stop if we run out of nodes to avoid an infinite loop.
    while (true) {
        current = current.getNextOuterFace(dir); // assumed traversal method
        if (current == null) {
            // If traversal fails, return a circulator to the stop node
            return new OuterFaceCirculator(stop, dir);
        }
        if (current == stop || predicate.apply(current)) {
            return new OuterFaceCirculator(current, dir);
        }
    }
}

