    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes must not be null");
    }

    // Initialize the circulator at the start node
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    if (circ == null) {
        // In case the circulator construction fails, return a circulator to stop
        return new OuterFaceCirculator(stop, dir);
    }

    try {
        Node current = circ.getNode();
        // Traverse until we find a node satisfying the predicate or reach the stop node
        while (true) {
            if (predicate.test(current)) {
                return circ;
            }
            if (current.equals(stop)) {
                return circ;
            }
            // Move to the next node in the specified direction
            circ = (dir >= 0) ? circ.next() : circ.prev();
            if (circ == null) {
                // If traversal goes out of bounds, fallback to stop node circulator
                return new OuterFaceCirculator(stop, dir);
            }
            current = circ.getNode();
        }
    } catch (RuntimeException e) {
        // Wrap any runtime exception into an unchecked exception with context
        throw new IllegalStateException("Error while traversing outer face", e);
    }
