    if (start == null) {
        throw new IllegalArgumentException("start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node must not be null");
    }

    // If the starting node already satisfies the predicate we return it.
    if (predicate.test(start)) {
        return new OuterFaceCirculator(start, dir);
    }

    // Fallback: return a circulator positioned at the stop node.
    try {
        return new OuterFaceCirculator(stop, dir);
    } catch (Exception e) {
        throw new IllegalStateException("unable to create circulator", e);
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node cur = circ.getNode();
    while (cur != stop) {
        if (predicate.test(cur)) {
            return circ;
        }
        circ.next();
        cur = circ.getNode();
    }
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes must not be null");
    }
    // Create a circulator beginning at the start node in the given direction
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // Traverse until we reach the stop node or a node satisfying the predicate
    while (!circ.node().equals(stop) && !predicate.test(circ.node())) {
        circ.next();
    }
    // At this point circ.node() is either the stop node or one that satisfies the predicate
    return circ;
}

