private void check(String modelName) throws IllegalStateException {
    try {
        Class<?> clazz = Class.forName(modelName);
        java.util.Set<Integer> indices = new java.util.HashSet<>();
        for (java.lang.reflect.Field field : clazz.getDeclaredFields()) {
            java.lang.annotation.Annotation[] annos = field.getAnnotations();
            for (java.lang.annotation.Annotation anno : annos) {
                java.lang.reflect.Method indexMethod;
                try {
                    indexMethod = anno.annotationType().getMethod("index");
                } catch (NoSuchMethodException e) {
                    continue;
                }
                Integer idx = (Integer) indexMethod.invoke(anno);
                indices.add(idx);
            }
        }
        if (indices.isEmpty()) {
            return;
        }
        int max = Integer.MIN_VALUE;
        for (int i : indices) {
            if (i > max) {
                max = i;
            }
        }
        for (int i = 0; i <= max; i++) {
            if (!indices.contains(i)) {
                throw new IllegalStateException("Sharding key indices are not continuous for model " + modelName);
            }
        }
    } catch (ClassNotFoundException e) {
        throw new IllegalStateException("Model class not found: " + modelName, e);
    } catch (IllegalAccessException e) {
        throw new IllegalStateException("Illegal access while checking model " + modelName, e);
    } catch (java.lang.reflect.InvocationTargetException e) {
        throw new IllegalStateException("Invocation target exception while checking model " + modelName, e);
    }
}

