protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    try{
        if(tour == null || graph == null){
            throw new IllegalArgumentException("tour and graph must not be null");
        }
        if(tour.isEmpty()){
            throw new IllegalArgumentException("tour must contain at least one edge");
        }
        // Build adjacency mapping
        Map<V, List<E>> adjacency = new HashMap<>();
        for(E e : tour){
            V v1 = graph.getEdgeSource(e);
            V v2 = graph.getEdgeTarget(e);
            if(v1 == null || v2 == null){
                throw new IllegalArgumentException("edge not present in graph");
            }
            adjacency.computeIfAbsent(v1, k -> new ArrayList<>()).add(e);
            adjacency.computeIfAbsent(v2, k -> new ArrayList<>()).add(e);
        }
        Iterator<E> it = tour.iterator();
        E startEdge = it.next();
        V startVertex = graph.getEdgeSource(startEdge);
        V current = startVertex;
        List<E> edgeList = new ArrayList<>();
        List<V> vertexList = new ArrayList<>();
        vertexList.add(startVertex);
        Set<E> remaining = new HashSet<>(tour);
        while(!remaining.isEmpty()){
            boolean found = false;
            List<E> neighbors = adjacency.getOrDefault(current, Collections.emptyList());
            for(E e : neighbors){
                if(remaining.contains(e)){
                    edgeList.add(e);
                    remaining.remove(e);
                    V next = graph.getEdgeSource(e).equals(current) ? graph.getEdgeTarget(e) : graph.getEdgeSource(e);
                    current = next;
                    vertexList.add(current);
                    found = true;
                    break;
                }
            }
            if(!found){
                throw new IllegalArgumentException("Edges do not form a contiguous tour");
            }
        }
        double weight = 0.0;
        for(E e : edgeList){
            weight += graph.getEdgeWeight(e);
        }
        return new GraphWalk<>(graph, startVertex, current, vertexList, edgeList, weight);
    }catch(Exception e){
        throw new IllegalArgumentException("Failed to transform edge set to tour: "+e.getMessage(), e);
    }
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if(tour==null || graph==null){
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if(tour.isEmpty()){
        throw new IllegalArgumentException("tour must contain at least one edge");
    }
    /* Build adjacency map from vertex to incident edges */
    Map<V, List<E>> adjacency = new HashMap<>();
    for(E e : tour){
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(e);
    }
    /* Start from an arbitrary vertex of the first edge */
    E firstEdge = tour.iterator().next();
    V start = graph.getEdgeSource(firstEdge);
    V current = start;
    /* Prepare lists for ordered vertices and edges */
    List<V> vertexSequence = new ArrayList<>();
    List<E> edgeSequence = new ArrayList<>();
    vertexSequence.add(current);
    Set<E> visitedEdges = new HashSet<>();
    /* Traverse until all edges are used */
    while(edgeSequence.size() < tour.size()){
        List<E> edgesAtV = adjacency.get(current);
        if(edgesAtV==null){
            throw new IllegalArgumentException("Provided edges do not form a connected tour");
        }
        E nextEdge = null;
        V nextVertex = null;
        for(E e : edgesAtV){
            if(visitedEdges.contains(e)) continue;
            V other = graph.getEdgeSource(e).equals(current) ? graph.getEdgeTarget(e) : graph.getEdgeSource(e);
            nextEdge = e;
            nextVertex = other;
            break;
        }
        if(nextEdge==null){
            throw new IllegalArgumentException("Cannot find next edge, invalid tour structure");
        }
        visitedEdges.add(nextEdge);
        edgeSequence.add(nextEdge);
        current = nextVertex;
        vertexSequence.add(current);
    }
    /* Compute total weight of the tour */
    double weight = 0.0;
    for(E e : edgeSequence){
        try{
            weight += graph.getEdgeWeight(e);
        }catch(Exception ignore){}
    }
    /* Create and return a SimpleGraphPath */
    return new SimpleGraphPath<>(graph, vertexSequence, edgeSequence, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        // Empty path: vertex list and edge list are empty
        return new GraphPathImpl<V,E>(graph, null, null, new ArrayList<E>(), 0.0);
    }

    // Make a mutable copy of the set of edges
    List<E> remaining = new ArrayList<E>(tour);
    List<E> ordered = new ArrayList<E>();

    // Start with any edge
    E first = remaining.remove(0);
    ordered.add(first);

    // Determine the current vertex for continuation
    V current;
    if (graph.isDirected()) {
        current = graph.getEdgeTarget(first);
    } else {
        current = graph.getEdgeSource(first);
    }

    // Build an ordered list of edges following the tour
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> it = remaining.iterator();
        while (it.hasNext()) {
            E e = it.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (graph.isDirected()) {
                if (src.equals(current)) {
                    current = tgt;
                    ordered.add(e);
                    it.remove();
                    found = true;
                    break;
                }
            } else {
                if (src.equals(current)) {
                    current = tgt;
                    ordered.add(e);
                    it.remove();
                    found = true;
                    break;
                } else if (tgt.equals(current)) {
                    current = src;
                    ordered.add(e);
                    it.remove();
                    found = true;
                    break;
                }
            }
        }
        if (!found) {
            // No compatible edge found – stop building the tour
            break;
        }
    }

    // Build the vertex list from the ordered edges
    List<V> vertices = new ArrayList<V>();
    V start;
    if (graph.isDirected()) {
        start = graph.getEdgeSource(first);
    } else {
        start = graph.getEdgeSource(first);
    }
    vertices.add(start);
    V prev = start;
    for (E e : ordered) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        V next;
        if (graph.isDirected()) {
            next = src.equals(prev) ? tgt : src;
        } else {
            next = src.equals(prev) ? tgt : src;
        }
        vertices.add(next);
        prev = next;
    }

    // Calculate total weight
    double totalWeight = 0.0;
    for (E e : ordered) {
        totalWeight += graph.getEdgeWeight(e);
    }

    V end = vertices.isEmpty() ? null : vertices.get(vertices.size() - 1);
    return new GraphPathImpl<V,E>(graph, start, end, ordered, totalWeight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()){
        return new GraphPathImpl<>(graph, null, null, null, 0);
    }
    // create a mutable copy of the tour edges
    LinkedHashSet<E> remaining = new LinkedHashSet<>(tour);
    Iterator<E> it = remaining.iterator();
    E first = it.next(); it.remove();
    List<E> orderedEdges = new ArrayList<>();
    orderedEdges.add(first);
    List<V> vertices = new ArrayList<>();
    V startVertex = graph.getEdgeSource(first);
    vertices.add(startVertex);
    V nextVertex = graph.getEdgeTarget(first);
    vertices.add(nextVertex);
    double totalWeight = graph.getEdgeWeight(first);

    while (!remaining.isEmpty()){
        boolean found = false;
        for (Iterator<E> rim = remaining.iterator(); rim.hasNext();){
            E e = rim.next();
            V src = graph.getEdgeSource(e);
            if (src.equals(nextVertex)){
                // Found next edge matching directed source
                rim.remove();
                orderedEdges.add(e);
                nextVertex = graph.getEdgeTarget(e);
                vertices.add(nextVertex);
                totalWeight += graph.getEdgeWeight(e);
                found = true;
                break;
            }
        }
        if (!found){
            // If graph undirected, try reversed connection
            for (Iterator<E> rim = remaining.iterator(); rim.hasNext();){
                E e = rim.next();
                V tgt = graph.getEdgeTarget(e);
                if (tgt.equals(nextVertex)){
                    // Use edge but treat as reversed
                    rim.remove();
                    orderedEdges.add(e);
                    V src = graph.getEdgeSource(e);
                    nextVertex = src;
                    vertices.add(nextVertex);
                    totalWeight += graph.getEdgeWeight(e);
                    found = true;
                    break;
                }
            }
        }
        if (!found){
            throw new IllegalArgumentException("Edges do not form a continuous tour");
        }
    }
    V endVertex = vertices.get(vertices.size() - 1);
    return new GraphPathImpl<>(graph, startVertex, endVertex, orderedEdges, totalWeight);
}

