                        sb.append((char) val);
                    } catch (NumberFormatException e) {
                        sb.append('\\').append(next);
                    }
                    i = j - 1;
                    continue;
                } else {
                    sb.append('\\').append(next);
                }
            } else if (next == 'n') {
                sb.append('\n');
            } else if (next == 't') {
                sb.append('\t');
            } else if (next == 'r') {
                sb.append('\r');
            } else if (next == 'b') {
                sb.append('\b');
            } else if (next == 'f') {
                sb.append('\f');
