    }
    int newPos = pos - elements;
    // Help GC by nulling out references to the popped elements
    for (int i = newPos; i < pos; ++i) {
        stack[i] = null;
    }
    pos = newPos;
}

private void pop(final int elements) { 
    if (elements < 0) { 
        throw new IllegalArgumentException("elements must be non-negative"); 
    } 
    if (pos < elements) { 
        throw new EmptyStackException(); 
    } 
