public static String stripFilenameExtension(String path){
    if (path == null) {
        return null;
    }
    // Find the last dot in the path
    int lastDotIndex = path.lastIndexOf('.');
    if (lastDotIndex < 0) {
        // No dot found
        return null;
    }
    // Find the last file separator (both Unix and Windows)
    int lastSlashIndex = path.lastIndexOf('/');
    int lastBackslashIndex = path.lastIndexOf('\\');
    int lastSeparatorIndex = Math.max(lastSlashIndex, lastBackslashIndex);
    // The extension must come after the last separator
    if (lastDotIndex <= lastSeparatorIndex) {
        return null;
    }
    // An extension must have at least one character after the dot
    if (lastDotIndex == path.length() - 1) {
        return null;
    }
    return path.substring(0, lastDotIndex);
}

