    }
    int n = bounds.size();
    java.util.List<Integer> suffix = new java.util.ArrayList<>(n);
    long suffixSum = 0;
    long totalSum = 0;
    for (int i = n - 1; i >= 0; i--) {
        int val = bounds.get(i);
        suffixSum += val;
        suffix.add((int)suffixSum);
        totalSum += val;
    }
    java.util.Collections.reverse(suffix);
    return new Pair<>(suffix, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    List<Integer> suffix = new ArrayList<>(bounds.size());
    long curSum = 0;
    long totalSum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--){
        int value = bounds.get(i);
        curSum += value;
        suffix.add(0, (int)curSum);
        totalSum += value;
    }
    return new Pair<>(suffix, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){ 
    if (bounds == null) { 
        throw new IllegalArgumentException("bounds cannot be null"); 
    } 
    int n = bounds.size(); 
    List<Integer> suffix = new ArrayList<>(n); 
    for (int i = 0; i < n; i++) { 
        suffix.add(0); 
    } 
    long totalSum = 0; 
    long suffixSum = 0; 
    for (int i = n - 1; i >= 0; i--) { 
        suffixSum += bounds.get(i); 
        suffix.set(i, (int) suffixSum); 
        totalSum += bounds.get(i); 
    } 
    return new Pair<>(suffix, totalSum); 
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null) {
        throw new IllegalArgumentException("bounds list cannot be null");
    }
    long totalSum = 0L;
    for (int val : bounds) {
        totalSum += val;
    }
    List<Integer> suffix = new ArrayList<>(bounds.size());
    int prefix = 0;
    for (int val : bounds) {
        long suffixVal = totalSum - prefix;
        suffix.add((int) suffixVal);
        prefix += val;
    }
    return new Pair<>(suffix, totalSum);
}

