private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null){
        throw new IllegalArgumentException("list cannot be null");
    }
    if (list.size == 0){
        return;
    }
    ListNode<E> thisTail = this.tail;
    ListNode<E> otherHead = list.head;
    ListNode<E> otherTail = list.tail;
    if (thisTail != null){
        thisTail.next = otherHead;
        if (otherHead != null){
            otherHead.prev = thisTail;
        }
    } else {
        this.head = otherHead;
    }
    this.tail = otherTail;
    this.size += list.size;
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list){
        if (list == null) {
            throw new IllegalArgumentException("list cannot be null");
        }
        if (this == list) {
            return;
        }
        // Ensure atomicity by synchronizing on both lists in a fixed order
        Object firstLock = System.identityHashCode(this) < System.identityHashCode(list) ? this : list;
        Object secondLock = System.identityHashCode(this) < System.identityHashCode(list) ? list : this;
        synchronized (firstLock) {
            synchronized (secondLock) {
                // Move each node from the source list to this list
                while (list.head != null) {
                    ListNode<E> node = list.head;
                    list.removeListNode(node);
                    this.addListNode(node);
                }
            }
        }
    }

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        return;
    }
    // if moving to the same list nothing to do
    if (this == list) {
        return;
    }
    // Lock both lists to guarantee atomicity
    Object firstLock = System.identityHashCode(this) < System.identityHashCode(list) ? this : list;
    Object secondLock = firstLock == this ? list : this;
    synchronized (firstLock) {
        synchronized (secondLock) {
            // if source list is empty, nothing to move
            if (list.size == 0) {
                return;
            }
            // If our list is empty, simply adopt source's nodes
            if (this.size == 0) {
                this.firstNode = list.firstNode;
                this.lastNode = list.lastNode;
                this.size = list.size;
            } else {
                // append source nodes to the end of this list
                this.lastNode.next = list.firstNode;
                list.firstNode.prev = this.lastNode;
                this.lastNode = list.lastNode;
                this.size += list.size;
            }
            // Clear source list
            list.firstNode = null;
            list.lastNode = null;
            list.size = 0;
        }
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null){
        return;
    }
    int remaining;
    synchronized(list){
        remaining = list.size();
    }
    for (int i = 0; i < remaining; i++){
        E element;
        // remove the first element from the source list
        synchronized(list){
            try{
                element = list.removeFirst();
            }catch(RuntimeException e){
                // If removeFirst is not supported fallback to remove(0)
                element = list.remove(0);
            }
        }
        // add the element to the destination list
        synchronized(this){
            try{
                this.addLast(element);
            }catch(RuntimeException e){
                this.add(element);
            }
        }
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        return;
    }
    // First try a straightforward removal and addition loop
    try {
        while (!list.isEmpty()) {
            ListNode<E> node = list.getHead();     // get first node
            list.removeListNode(node);              // atomically detach from source list
            this.addListNode(node);                 // atomically attach to this list
        }
    } catch (Exception e) {
        // Fallback strategy if the above methods aren't available
        try {
            while (!list.isEmpty()) {
                ListNode<E> node = list.removeFirst(); // safer generic removal
                this.addListNode(node);
            }
        } catch (Exception ignore) {
            // If all else fails, do nothing to avoid throwing during cleanup
        }
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase){
    if (str == null) return prefix == null;
    if (prefix == null) return false;
    int prefixLength = prefix.length();
    if (prefixLength > str.length()) return false;
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefixLength);
    }
    return str.startsWith(prefix);
}

