    if (prefix.length() > str.length()) {
        return false;
    }
    try {
        return str.regionMatches(ignoreCase, 0, prefix, 0, prefix.length());
    } catch (IndexOutOfBoundsException e) {
        // Should not happen due to length checks, but handle gracefully
        return false;
    }
}

