    // Assume there is a getName() method that returns the full name.
    String fullName = getName();
    if (fullName == null || fullName.isEmpty()) {
        return;
    }
    int start = nameStart;
    if (start < 0) {
        start = 0;
    } else if (start > fullName.length()) {
        start = fullName.length();
    }
    StringBuilder abbreviation = new StringBuilder();
    int i = start;
    while (i < fullName.length()) {
        // Skip any whitespace before a word.
        while (i < fullName.length() && Character.isWhitespace(fullName.charAt(i))) {
            i++;
        }
        if (i >= fullName.length()) {
            break;
        }
        // Take the first letter of the word.
        abbreviation.append(Character.toUpperCase(fullName.charAt(i)));
        // Advance to the end of the word.
        while (i < fullName.length() && !Character.isWhitespace(fullName.charAt(i))) {
            i++;
        }
    }
    buf.append(abbreviation);
}

