    if (start < 0) {
        start = 0;
    }
    if (start > name.length()) {
        return;
    }

    // Extract the portion of the name that needs to be abbreviated
    String remaining = name.substring(start);

    // Split on whitespace to get individual words
    String[] parts = remaining.trim().split("\\s+");
    if (parts.length == 0) {
