private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set cannot be null");
    }
    if (vertices.size() <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2) && graph.getEdge(v1, v2) == null) {
                return false;
            }
        }
    }
    return true;
}

