    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2)) {
                E edge = graph.getEdge(v1, v2);
                if (edge == null) {
                    edge = graph.getEdge(v2, v1); // handle directed graphs
                }
                if (edge == null) {
                    return false;
                }
            }
        }
    }
    return true;
}

