private List<Integer> computeLowerBounds(List<K> keys){
    // Handle null input
    if (keys == null) {
        return java.util.Collections.emptyList();
    }
    // Prepare result list with same capacity as input list
    List<Integer> lowerBounds = new java.util.ArrayList<>(keys.size());
    for (K key : keys) {
        Integer bound = null;
        try {
            if (key == null) {
                // Preserve null position for missing key
                bound = null;
            } else if (key instanceof java.lang.Number) {
                // If key is a numeric type, use its integer value
                bound = ((java.lang.Number) key).intValue();
            } else {
                // Default fallback for non‑numeric keys
                bound = 0;
            }
        } catch (Exception e) {
            // In case of any unexpected runtime issue, record a sentinel value
            bound = null;
        }
        lowerBounds.add(bound);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
        List<Integer> bounds = new ArrayList<>();
        if (keys == null || keys.isEmpty()) return bounds;
        TreeSet<Integer> set = new TreeSet<>();
        try {
            for (K k : keys) {
                set.add((Integer) k);
            }
        } catch (ClassCastException e) {
            throw new IllegalArgumentException("Keys must be of type Integer", e);
        }
        for (K k : keys) {
            Integer val = (Integer) k;
            Integer lower = set.lower(val);
            bounds.add(lower);
        }
        return bounds;
    }

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null) return result;
    for (K k : keys){
        if (!(k instanceof Integer)){
            result.add(null);
            continue;
        }
        Integer keyVal = (Integer) k;
        Integer maxLower = null;
        for (K o : keys){
            if (o == null || o == k) continue;
            if (o instanceof Integer){
                Integer val = (Integer) o;
                if (val < keyVal){
                    if (maxLower == null || val > maxLower){
                        maxLower = val;
                    }
                }
            }
        }
        result.add(maxLower);
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++){
        Object curr = keys.get(i);
        int maxLower = Integer.MIN_VALUE;
        for (int j = 0; j < keys.size(); j++){
            if (i == j) continue;
            Object other = keys.get(j);
            if (curr instanceof Integer && other instanceof Integer){
                int currVal = (Integer) curr;
                int otherVal = (Integer) other;
                if (otherVal < currVal && otherVal > maxLower){
                    maxLower = otherVal;
                }
            }
        }
        bounds.add(maxLower == Integer.MIN_VALUE ? 0 : maxLower);
    }
    return bounds;
}

