                while (index < length && descriptor.charAt(index) == '[') {
                    index++;
                }
                // after brackets, pop one slot for the array reference
                stack.pop();
            } else { // primitive
                int count = (c == 'J' || c == 'D') ? 2 : 1;
                for (int n = 0; n < count; n++) {
                    stack.pop();
                }
                index++;
            }
        }
        // skip ')', return type is not popped
    } else {
        // single type descriptor
        char c = descriptor.charAt(index);
        if (c == 'L') {
            int semicolon = descriptor.indexOf(';', index);
            if (semicolon == -1) {
                throw new IllegalArgumentException("Invalid descriptor: missing ';'");
            }
            stack.pop();
        } else if (c == '[') {
            while (index < length && descriptor.charAt(index) == '[') {
                index++;
            }
            // pop one slot for the array reference
            stack.pop();
        } else { // primitive
            int count = (c == 'J' || c == 'D') ? 2 : 1;
            for (int n = 0; n < count; n++) {
                stack.pop();
            }
        }
    }
