    while (idx < len) {
        char ch = descriptor.charAt(idx);
        if (ch == ')') {
            // reached end of arguments in a method descriptor
            break;
        }
        switch (ch) {
            case '[': {
                // skip all successive '[' characters
                do {
                    idx++;
                } while (idx < len && descriptor.charAt(idx) == '[');
                if (idx >= len) {
                    return; // malformed descriptor
                }
                // now at the concrete type descriptor of the array
                if (descriptor.charAt(idx) == 'L') {
                    idx++; // skip 'L'
                    while (idx < len && descriptor.charAt(idx) != ';') {
                        idx++;
                    }
                }
                // array occupies one slot
                pos--;
                if (idx < len && descriptor.charAt(idx) == ';') {
                    idx++; // skip terminator
                }
                break;
            }
            case 'L': {
                // object type: skip until ';'
                idx++; // skip 'L'
                while (idx < len && descriptor.charAt(idx) != ';') {
                    idx++;
                }
                pos--;
                if (idx < len && descriptor.charAt(idx) == ';') {
                    idx++; // skip terminator
                }
                break;
            }
            case 'J':
            case 'D': {
                // long and double take two slots
                pos -= 2;
                idx++;
                break;
            }
            default: {
                // primitive types take one slot
                pos--;
                idx++;
                break;
            }
        }
        // keep position non‑negative
        if (pos < 0) {
            pos = 0;
        }
    }
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    try {
        int index = 0;
        if (descriptor.charAt(0) == '(') {
            index = 1;
            while (index < descriptor.length() && descriptor.charAt(index) != ')') {
                char c = descriptor.charAt(index);
                int slots;
                if (c == 'L') {
                    int semicolon = descriptor.indexOf(';', index);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Malformed descriptor");
                    }
                    slots = 1;
                    index = semicolon + 1;
                } else if (c == '[') {
                    while (descriptor.charAt(index) == '[') {
                        index++;
                    }
                    index++; // skip base type
                    slots = 1;
                } else if (c == 'J' || c == 'D') {
                    slots = 2;
                    index++;
                } else if (c == 'V') {
                    slots = 0;
                    index++;
                } else {
                    slots = 1;
                    index++;
                }
                while (slots-- > 0) {
                    if (--pos < 0) {
                        throw new IndexOutOfBoundsException("Stack underflow");
                    }
                    stack[pos] = null;
                }
            }
        } else {
            char c = descriptor.charAt(0);
            int slots;
            if (c == 'L') {
                int semicolon = descriptor.indexOf(';', 0);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Malformed descriptor");
                }
                slots = 1;
            } else if (c == '[') {
                int idx = 0;
                while (descriptor.charAt(idx) == '[') {
                    idx++;
                }
                idx++; // base type
                slots = 1;
            } else if (c == 'J' || c == 'D') {
                slots = 2;
            } else if (c == 'V') {
                slots = 0;
            } else {
                slots = 1;
            }
            while (slots-- > 0) {
                if (--pos < 0) {
                    throw new IndexOutOfBoundsException("Stack underflow");
                }
                stack[pos] = null;
            }
        }
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int slots = 0;
    try {
        int i = 0;
        int len = descriptor.length();
        if (descriptor.charAt(0) == '(') {
            // Method descriptor: pop all argument types
            i = 1; // skip '('
            while (i < len && descriptor.charAt(i) != ')') {
                // Skip any array brackets
                while (descriptor.charAt(i) == '[') {
                    i++;
                }
                char type = descriptor.charAt(i);
                int incr = 1;
                if (type == 'J' || type == 'D') {
                    incr = 2;
                }
                if (type == 'L') {
                    int semi = descriptor.indexOf(';', i);
                    if (semi == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    i = semi + 1;
                } else {
                    i++;
                }
                slots += incr;
            }
            // Return type is ignored
        } else {
            // Single type descriptor: pop it
            if (descriptor.charAt(0) == '[') {
                // Skip all '['
                int j = 0;
                while (descriptor.charAt(j) == '[') {
                    j++;
                }
                char type = descriptor.charAt(j);
                if (type == 'L') {
                    int semi = descriptor.indexOf(';', j);
                    if (semi == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                }
                slots = 1; // array occupies one slot
            } else {
                char type = descriptor.charAt(0);
                slots = (type == 'J' || type == 'D') ? 2 : 1;
            }
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }
    pos -= slots;
    if (pos < 0) {
        throw new IllegalStateException("Frame stack underflow – attempted to pop " + slots + " slots");
    }
}

