private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    for (K key : keys) {
        if (key == null) {
            bounds.add(0);
        } else if (key instanceof Integer) {
            bounds.add((Integer) key);
        } else {
            bounds.add(key.hashCode());
        }
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    List<Integer> upperBounds = new ArrayList<>();
    for (K key : keys) {
        try {
            if (key == null) {
                upperBounds.add(0);
                continue;
            }
            if (key instanceof Number) {
                Number num = (Number) key;
                long value = num.longValue();
                if (value > Integer.MAX_VALUE) {
                    upperBounds.add(Integer.MAX_VALUE);
                } else if (value < Integer.MIN_VALUE) {
                    upperBounds.add(Integer.MIN_VALUE);
                } else {
                    upperBounds.add((int) value);
                }
            } else {
                upperBounds.add(Math.abs(key.hashCode()));
            }
        } catch (Exception e) {
            // In case of any unexpected error, add a default value
            upperBounds.add(0);
        }
    }
    return upperBounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    for (K key : keys) {
        try {
            bounds.add(key == null ? 0 : key.hashCode());
        } catch (Exception e) {
            bounds.add(0);
        }
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> upperBounds = new java.util.ArrayList<>(keys.size());
    for (K key : keys) {
        // Using the hashCode of the key as an upper bound value
        // (Abs value to avoid negative values)
        int bound = Math.abs(key.hashCode());
        upperBounds.add(bound);
    }
    return upperBounds;
}

private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>();
    if (keys == null) {
        return upperBounds;
    }
    for (K key : keys) {
        try {
            if (key == null) {
                upperBounds.add(null);
            } else {
                // Assume key can be cast to a Number; otherwise skip
                Number num = (Number) key;
                upperBounds.add(num.intValue());
            }
        } catch (ClassCastException e) {
            // If the key is not a Number, record null to indicate no bound
            upperBounds.add(null);
        }
    }
    return upperBounds;
}

