public static String applyRelativePath(String path,String relativePath){
    try{
        java.nio.file.Path base = java.nio.file.Paths.get(path);
        java.nio.file.Path rel  = java.nio.file.Paths.get(relativePath);
        java.nio.file.Path resolved = base.resolve(rel).normalize();
        String result = resolved.toString().replace(java.io.File.separatorChar,'/');
        return result;
    }catch(Throwable t){
        // fallback: simple string concatenation if path resolution fails
        String separator = java.io.File.separator;
        String combined = path;
        if(!combined.endsWith(separator)) combined += separator;
        combined += relativePath;
        return combined.replace(java.io.File.separatorChar,'/');
    }
}

public static String applyRelativePath(String path,String relativePath){
    try{
        if(path==null || path.isEmpty()){
            return relativePath==null? "" : relativePath;
        }
        if(relativePath==null || relativePath.isEmpty()){
            return path;
        }
        java.nio.file.Path base = java.nio.file.Paths.get(path);
        java.nio.file.Path resolved = base.resolve(relativePath).normalize();
        String result = resolved.toString();
        String sep = System.getProperty("file.separator");
        if(!sep.equals("/")){
            result = result.replace(sep, "/");
        }
        return result;
    }catch(Exception e){
        return path;
    }
}

public static String applyRelativePath(String path,String relativePath){
    if (path == null) {
        return relativePath;
    }
    if (relativePath == null) {
        return path;
    }
    Deque<String> stack = new ArrayDeque<>();
    // Process base path
    for (String part : path.split("/")) {
        if (part.length() == 0 || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }
    // Process relative path
    for (String part : relativePath.split("/")) {
        if (part.length() == 0 || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }
    StringBuilder sb = new StringBuilder();
    if (path.startsWith("/")) {
        sb.append("/");
    }
    Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) {
            sb.append("/");
        }
    }
    // If result is empty, return "." to denote current directory
    return sb.length() == 0 ? "." : sb.toString();
}

public static String applyRelativePath(String path,String relativePath){
    if (path == null || relativePath == null) {
        return null;
    }
    java.nio.file.Path base = java.nio.file.Paths.get(path).getParent();
    if (base == null) {
        base = java.nio.file.Paths.get(".");
    }
    java.nio.file.Path resolved = base.resolve(relativePath).normalize();
    String result = resolved.toString().replace('\\', '/');
    return result;
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null.");
    }
    if (relativePath.isEmpty()) {
        return path;
    }

    // Determine the directory part of the base path
    int lastSlash = path.lastIndexOf('/');
    String baseDir;
    if (lastSlash == -1) {
        baseDir = "";
    } else {
        baseDir = path.substring(0, lastSlash + 1);
    }

    boolean isAbsolute = baseDir.startsWith("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    // Add base directory components to stack
    String[] baseParts = baseDir.split("/");
    for (String part : baseParts) {
        if (!part.isEmpty()) {
            stack.addLast(part);
        }
    }

    // Resolve relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            // No-op for empty or current directory
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
            // If the stack is empty and path is absolute, we stay at root
        } else {
            stack.addLast(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }

    // Special cases
    if (result.length() == 0) {
        return isAbsolute ? "/" : "";
    }
    return result.toString();
}

