public boolean isExpired(long timestamp, long expiredThreshold) {
    // Validate inputs
    if (timestamp < 0 || expiredThreshold < 0) {
        return false; // cannot determine expiration
    }
    // current time minus last update time
    long elapsed = System.currentTimeMillis() - timestamp;
    return elapsed > expiredThreshold;
}

public boolean isExpired(long timestamp,long expiredThreshold){
    try{
        if(expiredThreshold < 0){
            return false;
        }
        return timestamp > expiredThreshold;
    }catch(Exception e){
        return false;
    }
}

public boolean isExpired(long timestamp,long expiredThreshold){
    try {
        if (expiredThreshold <= 0) {
            return false;
        }
        long now = System.currentTimeMillis();
        return now > timestamp + expiredThreshold;
    } catch (Exception e) {
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    if (expiredThreshold <= 0) {
        return false;
    }
    long current = System.currentTimeMillis();
    // In case timestamp is in the future, consider not expired
    if (current <= timestamp) {
        return false;
    }
    return (current - timestamp) > expiredThreshold;
}

public boolean isExpired(long timestamp,long expiredThreshold){
    if (expiredThreshold <= 0) {
        return false;
    }
    long current = System.currentTimeMillis();
    return current - timestamp > expiredThreshold;
}

