            if (e.getFrom().equals(_previousNode) && e.getTo().equals(_nextNode)){
                return e;
            }
            // Virtual node handling – assume real counterpart comparison
            if (e.getFrom() == _previousNode || e.getTo() == _nextNode){
                return e;
