int function() throws IOException {
    int first = in.read();
    if (first == -1) {
        return 0;
    }
    int result = first & 0x7F;
    if ((first & 0x80) == 0) {
        return result;
    }
    int shift = 7;
    int next;
    while (true) {
        if (shift >= 32) {
            throw new IOException("Varint too long");
        }
        next = in.read();
        if (next == -1) {
            throw new IOException("EOF while reading varint");
        }
        result |= (next & 0x7F) << shift;
        if ((next & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
}

int readTag() throws IOException {
    // Attempt to read a varint-encoded tag.  If we hit EOF, return 0.
    int result = 0;
    int shift = 0;
    while (true) {
        int b;
        try {
            b = read();
        } catch (EOFException e) {
            // End of stream reached – return zero as the sentinel tag.
            return 0;
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
        if (shift > 35) {
            throw new IOException("Malformed varint");
        }
    }
    return result;
}

