private String buildContentRange(){
    // Compute the Content-Range header value
    // Return null if required fields are invalid or not set
    if (contentRangeStart < 0 || contentRangeEnd < 0 || contentLength <= 0) {
        return null;
    }
    // Format: "bytes start-end/totalLength"
    return String.format("bytes %d-%d/%d", contentRangeStart, contentRangeEnd, contentLength);
}

private String buildContentRange(){
    if (start < 0 || end < start) {
        return null;
    }
    StringBuilder sb = new StringBuilder("bytes ");
    sb.append(start).append('-').append(end);
    sb.append('/');
    sb.append(total >= 0 ? total : '*');
    return sb.toString();
}

private String buildContentRange() {
        try {
            Long start = this.contentRangeStart;
            Long end   = this.contentRangeEnd;
            Long total = this.contentLength;

            if (start == null || end == null) {
                return null; // cannot build header without start/end
            }

            if (start > end) {
                throw new IllegalArgumentException("Content range start (" + start + ") is greater than end (" + end + ")");
            }

            if (total != null && total > 0) {
                return "bytes " + start + "-" + end + "/" + total;
            } else {
                return "bytes " + start + "-" + end + "/*";
            }
        } catch (IllegalArgumentException e) {
            throw e; // rethrow for caller to handle
        } catch (Exception e) {
            throw new RuntimeException("Failed to build Content-Range header", e);
        }
    }

private String buildContentRange(){
    // Example: Content-Range: bytes 0-499/1234
    if (start < 0 || end < start || totalSize <= 0) {
        return null;
    }
    return String.format("bytes %d-%d/%d", start, end, totalSize);
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("File must not be null");
    }
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Attempt to parse a snapshot from the line. If parsing fails, skip the line.
            ThreadSnapshot snapshot;
            try {
                snapshot = ThreadSnapshot.parse(line);
            } catch (Exception e) {
                // Log the error or continue silently
                continue;
            }
            if (snapshot == null) {
                continue;
            }
            // If no time ranges are supplied, accept all snapshots.
            if (timeRanges == null || timeRanges.isEmpty()) {
                result.add(snapshot);
                continue;
            }
            long tsTime = snapshot.getTimestamp(); // Assumed method
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) {
                    continue;
                }
                long start = range.getStartTime(); // Assumed method
                long end = range.getEndTime();     // Assumed method
                if (tsTime >= start && tsTime <= end) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    }
    return result;
}

