public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null) {
        throw new IllegalArgumentException("File must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IOException("File does not exist or is not a regular file: " + file);
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        // No time ranges specified, load all snapshots
        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = br.readLine()) != null) {
                ThreadSnapshot snapshot = parseLine(line);
                if (snapshot != null) {
                    result.add(snapshot);
                }
            }
        }
        return result;
    }
    // Helper to determine if a timestamp is within any of the provided ranges
    java.util.function.Predicate<Long> inAnyRange = ts -> {
        for (ProfileAnalyzeTimeRange r : timeRanges) {
            long start = (long) r.getStartMillis(); // assuming getter exists
            long end = (long) r.getEndMillis();     // assuming getter exists
            if (ts >= start && ts <= end) {
                return true;
            }
        }
        return false;
    };
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            ThreadSnapshot snapshot = parseLine(line);
            if (snapshot != null) {
                long ts = snapshot.getTimestamp(); // assuming getter exists
                if (inAnyRange.test(ts)) {
                    result.add(snapshot);
                }
            }
        }
    } catch (NumberFormatException e) {
        // Log or rethrow as needed
        throw new IOException("Failed to parse snapshot line: " + e.getMessage(), e);
    }
    return result;
}

private static ThreadSnapshot parseLine(String line) {
    if (line == null || line.trim().isEmpty()) {
        return null;
    }
    String[] parts = line.split(",", 3);
    if (parts.length < 2) {
        return null;
    }
    try {
        long timestamp = Long.parseLong(parts[0].trim());
        int threadId = Integer.parseInt(parts[1].trim());
        String threadName = parts.length == 3 ? parts[2].trim() : "";
        return new ThreadSnapshot(timestamp, threadId, threadName);
    } catch (NumberFormatException e) {
        // Invalid numeric format; skip this line
        return null;
    }
}
